import {endpoint,net,colourCodes,layoutInfo} from './model.mjs';
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));
const text=(x,y,value,cls='',anchor='middle')=>`<text x="${x}" y="${y}" class="${cls}" text-anchor="${anchor}">${esc(value)}</text>`;
import {visuals} from './components.mjs';
export {visuals};
import {routeDiagram} from './routing.mjs';
const categoryColours={signal:'#303b43',ground:'#7a8187',tone:'#ad2929',switching:'#926f31'};
function isActive(c,kind,id,selection,filter){
 if(selection?.kind==='component'){if(kind==='component')return id===selection.id;if(kind==='wire'){const w=c.connections.find(w=>w.id===id);return w.from.startsWith(selection.id+'.')||w.to.startsWith(selection.id+'.');}}
 if(selection?.kind==='wire'){const selected=c.connections.find(w=>w.id===selection.id);if(selected){const refs=net(c,selected.from);return kind==='wire'?refs.has(c.connections.find(w=>w.id===id).from):[...refs].some(r=>r.startsWith(id+'.'));}}
 if(selection?.kind==='stage'){return kind==='component'?selection.ids.includes(id):c.connections.some(w=>w.id===id&&(selection.ids.some(p=>w.from.startsWith(p+'.')||w.to.startsWith(p+'.'))));}
 if(filter!=='all'){if(kind==='wire')return c.connections.find(w=>w.id===id).category===filter;return c.connections.some(w=>w.category===filter&&(w.from.startsWith(id+'.')||w.to.startsWith(id+'.')));}
 return true;
}
export function drawCircuit(c,{selection=null,filter='all',exporting=false,view='full'}={}){
 const routes=routeDiagram(c);
 const codes=colourCodes[c.state.colours];
 const meta=`${layoutInfo[c.state.guitar].label} / ${c.state.wiring.toUpperCase()} / SELECTOR ${c.state.position.toUpperCase()}`;
 const labelLayer=[];
 for(const part of c.components)if(!['capacitor','resistor','network'].includes(part.type))labelLayer.push(`<g transform="translate(${part.x} ${part.y})" class="${part.existing?'not-supplied':''} ${isActive(c,'component',part.id,selection,filter)?'':'muted'}">${text(['humbucker','singlecoil'].includes(part.type)?77:['blade','superswitch'].includes(part.type)?95:0,part.type==='pot'?8:-20,part.label,'part-title')}</g>`);
 const bodies=c.components.map(part=>`<g class="component ${part.existing?'not-supplied':'supplied'} ${isActive(c,'component',part.id,selection,filter)?'':'muted'}" transform="translate(${part.x} ${part.y})" data-component="${part.id}" ${exporting?'':`tabindex="0" role="button" aria-label="Inspect ${esc(part.label)}"`}><title>${esc(part.label+' / '+part.value)}</title>${visuals[part.type](part).replace(/<text[\s\S]*?<\/text>/g,label=>{labelLayer.push(`<g transform="translate(${part.x} ${part.y})" class="${part.existing?'not-supplied':''} ${isActive(c,'component',part.id,selection,filter)?'':'muted'}">${label}</g>`);return '';})}</g>`).join('');
 const contacts=c.contacts.filter(([a])=>['blade','superswitch'].includes(endpoint(c,a).component.type)).map(([a,b])=>{const p=endpoint(c,a),q=endpoint(c,b);return `<path stroke="#926f31" stroke-width="2" stroke-dasharray="4 3" fill="none" d="M${p.x} ${p.y}V${p.y+45}H${q.x}V${q.y}"/>`;}).join('');
 const wires=c.connections.map(w=>{
  const a=endpoint(c,w.from),b=endpoint(c,w.to),points=routes.get(w.id),d=points.map((p,i)=>(i?'L':'M')+p.join(' ')).join(' '),active=isActive(c,'wire',w.id,selection,filter),colour=w.conductor?codes.wires[w.conductor][0]:categoryColours[w.category];
  return `<g class="wire ${(w.supplied===false||w.supplied===undefined&&(a.component.existing||b.component.existing))?'not-supplied':'supplied'} ${active?'':'muted'}" data-wire="${w.id}" ${exporting?'':`tabindex="0" role="button" aria-label="Trace ${esc(a.component.label+' '+a.terminal.label+' to '+b.component.label+' '+b.terminal.label)}"`}><title>${esc(w.from+' → '+w.to)}</title><path class="wire-clear" d="${d}"/><path class="wire-line ${w.conductor==='shield'?'bare-wire':''}" stroke="${colour||categoryColours[w.category]}" d="${d}"/>${exporting?'':`<path class="wire-hit" d="${d}"/>`}</g>`;
 }).join('');
 const terminals=c.components.map(part=>`<g class="anchors ${part.existing?'not-supplied':''} ${isActive(c,'component',part.id,selection,filter)?'':'muted'}">${Object.entries(part.terminals).map(([key,t])=>{const x=part.x+t.x,y=part.y+t.y,ref=part.id+'.'+key,count=c.connections.filter(w=>w.from===ref||w.to===ref).length;return `${count?`<ellipse class="solder-joint" cx="${x}" cy="${y}" rx="${key==='case'?10:7}" ry="${key==='case'?7:6}"/>`:''}${count>1?`<circle class="junction" cx="${x}" cy="${y}" r="3"/>`:''}<circle class="terminal" cx="${x}" cy="${y}" r="5" data-terminal="${part.id+'.'+key}" ${exporting?'':`tabindex="0" role="button" aria-label="Inspect ${esc(part.label+' '+t.label)}"`}><title>${esc(part.label+' / '+t.label)}</title></circle>`;}).join('')}</g>`).join('');
 const conductors=c.components.filter(p=>['humbucker','singlecoil','p90'].includes(p.type)).map(p=>`<g class="${p.existing?'not-supplied':''} ${isActive(c,'component',p.id,selection,filter)?'':'muted'}">`+Object.keys(p.terminals).map(key=>{const t=p.terminals[key],colour=p.type==='humbucker'?codes.wires[key][0]:categoryColours[key==='hot'?'signal':'ground'];return `<path class="pickup-conductor" stroke="${colour}" d="M${p.x+180} ${p.y+118}Q${p.x+185} ${p.y+t.y} ${p.x+t.x} ${p.y+t.y}"/>`;}).join('')+'</g>').join('');
 return `<svg xmlns="http://www.w3.org/2000/svg" id="generator-svg" data-view="${view}" viewBox="0 0 1320 1275" role="group" aria-labelledby="generator-title generator-desc"><title id="generator-title">Apparition ${esc(meta)} wiring diagram</title><desc id="generator-desc">Physical component connection diagram. Rear-view pots, lugs down, numbered 3, 2, 1 from left to right. Solder ovals mark physical terminations; filled dots mark shared-terminal junctions. Separated crossings do not connect. Pickup wire code: ${esc(codes.label)}. Toggle and jack terminals are identified by function; verify your hardware.</desc><style>
 text{pointer-events:none;font-family:'JetBrains Mono',monospace;fill:#262626;font-size:14px}.part-title{font-size:15px;font-weight:600;paint-order:stroke;stroke:#f5f5f5;stroke-width:5px;stroke-linejoin:round}.part-value{font-size:14px;paint-order:stroke;stroke:#f5f5f5;stroke-width:4px}.micro{font-size:12px;fill:#666}.terminal-label{font-size:13px;font-weight:bold;paint-order:stroke;stroke:#f5f5f5;stroke-width:4px}[data-view="kit"] .not-supplied{opacity:.24}[data-view="kit"] .supplied .metal{stroke:#927344}.solder-joint{fill:#b9bdba;stroke:#666;stroke-width:1}.junction{fill:#252525}.case-pad{fill:#b5b6b2;stroke:#93958f}.pickup-cable{stroke:#333;stroke-width:10;fill:none;stroke-linecap:round}.coil-label{font-size:10px;fill:#333}.light-label{fill:#ddd}.disc-body{fill:#b68047;stroke:#81552c;stroke-width:2}.film-body{fill:#afac8a;stroke:#73725c;stroke-width:2}.common-lug{stroke:#61491e;stroke-width:3}.metal{fill:#d5d5d2;stroke:#666;stroke-width:2}.rim{fill:none;stroke:#a4a4a0;stroke-width:1}.board{fill:#bc9d67;stroke:#7f6945;stroke-width:2}.pickup-base{fill:#aaa;stroke:#666;stroke-width:2}.bobbin-light{fill:#d2bd93;stroke:#777}.bobbin-dark{fill:#303234;stroke:#111}.screw{fill:#c1c2bd;stroke:#666}.screw-slot{stroke:#333;stroke-width:1.5}.lead{stroke:#858585;stroke-width:3;fill:none}.cap-body{fill:#ca6b32;stroke:#913f19;stroke-width:2}.resistor-body{fill:#d6c19c;stroke:#8b7656;stroke-width:2}.resistor-band{stroke:#775d3f;stroke-width:4}.switch-leaf{stroke:#777;stroke-width:4;fill:none}.jack-hole{fill:#f5f5f5;stroke:#555}.ground-symbol{stroke:#666;stroke-width:3;fill:none}.terminal{fill:transparent;stroke:#735b32;stroke-width:2}.wire-clear{stroke:#f5f5f5;stroke-width:8;fill:none;stroke-linejoin:round}.wire-line{stroke-width:3;fill:none;stroke-linejoin:round}.bare-wire{stroke-dasharray:5 3}.wire-hit{stroke:transparent;stroke-width:14;fill:none;cursor:pointer}.insulation{fill:#303234;stroke:#f5f5f5;stroke-width:2}.pickup-conductor{stroke-width:4;fill:none}.muted{opacity:.18}.component,.wire,.terminal{cursor:pointer}.component:focus,.wire:focus{outline:none}.component:focus .metal,.component:focus .pickup-base,.wire:focus .wire-line{stroke:#b91c1c;stroke-width:4}.terminal:focus{stroke:#b91c1c;stroke-width:4;outline:none}.sheet-caption{font-size:12px;fill:#666}
 </style><rect width="1320" height="1275" fill="#f5f5f5"/>${text(35,28,meta,'part-title','start')}${text(35,49,'REAR VIEW · LUGS DOWN · 1 = CCW END / 2 = WIPER / 3 = CW END','sheet-caption','start')}${bodies}${contacts}${wires}${conductors}${labelLayer.join('')}${c.components.filter(p=>p.type==='humbucker').map(p=>`<g class="${isActive(c,'component',p.id,selection,filter)?'':'muted'}">${text(p.x,p.y+156,'HOT: '+(c.state.colours==='generic'?'N START':codes.wires.hot[1]),'sheet-caption','start')}${text(p.x,p.y+174,'JOIN: '+(c.state.colours==='generic'?'N FIN + S FIN':codes.wires.linkA[1]+' + '+codes.wires.linkB[1]),'sheet-caption','start')}${text(p.x,p.y+192,'GROUND: '+(c.state.colours==='generic'?'S START':codes.wires.ground[1]),'sheet-caption','start')}${text(p.x,p.y+210,'SHIELD: '+codes.wires.shield[1],'sheet-caption','start')}</g>`).join('')}${terminals}${text(35,1210,'FILLED DOT = SHARED TERMINAL. SILVER OVAL = SOLDER JOINT. SEPARATED CROSSINGS DO NOT JOIN.','sheet-caption','start')}${text(35,1232,(view==='kit'?'MUTED: EXISTING / NOT INCLUDED. ':'')+'RED: TONE / GREY: GROUND / DARK: SIGNAL / GOLD: SWITCHING / DASHED GOLD: CLOSED SWITCH CONTACT.','sheet-caption','start')}${text(35,1254,c.state.guitar==='prs'?'SUPERSWITCH CONVERSION, NOT FACTORY PRS PINOUT. Verify pole identity and pickup coil polarity.':'Generic hardware outline: verify lug functions, viewing orientation and continuity on the actual parts.','sheet-caption','start')}</svg>`;
}
